description:
{
  "image_category": "SIGN_ILLUSTRATION",
  "summary": "Hình ảnh minh họa các dạng đèn tín hiệu giao thông theo QCVN 41:2024/BGTVT, bao gồm 9 dạng với nhiều kiểu bố trí và chức năng khác nhau.",
  "items": [
    {
      "identifier": "Dạng đèn 1",
      "visual_or_geometric_features": "3 đèn tròn xếp dọc (đỏ, vàng, xanh) hoặc kết hợp với đèn mũi tên (trái/phải/quay đầu) ở vị trí ngang hoặc dọc.",
      "meaning_or_specification": "Đèn thường dùng; đèn mũi tên báo hiệu cho phép đi thẳng, rẽ trái, rẽ phải hoặc quay đầu."
    },
    {
      "identifier": "Dạng đèn 2",
      "visual_or_geometric_features": "Các đèn hình mũi tên (trên, dưới, trái, phải, chéo) với 3 màu (đỏ, vàng, xanh).",
      "meaning_or_specification": "Điều khiển phương tiện theo hướng cụ thể (dừng, chờ, đi)."
    },
    {
      "identifier": "Dạng đèn 3",
      "visual_or_geometric_features": "Bên trái: 2 đèn tròn có gạch chéo màu đỏ; bên phải: đèn mũi tên màu xanh.",
      "meaning_or_specification": "Khi đèn đỏ sáng: dừng lại; khi đèn xanh sáng: được phép đi theo hướng mũi tên."
    },
    {
      "identifier": "Dạng đèn 4",
      "visual_or_geometric_features": "2 đèn tròn (đỏ và xanh), bố trí theo chiều dọc (đỏ trên, xanh dưới) hoặc ngang (đỏ trái, xanh phải).",
      "meaning_or_specification": "Đèn đỏ: dừng lại; đèn xanh: được đi."
    },
    {
      "identifier": "Dạng đèn 5",
      "visual_or_geometric_features": "Đèn tròn màu đỏ (kiểu 1) hoặc đèn chữ thập màu đỏ (kiểu 2).",
      "meaning_or_specification": "Cấm đi, đặt phía sau nút giao theo chiều đi."
    },
    {
      "identifier": "Dạng đèn 6",
      "visual_or_geometric_features": "4 đèn tròn màu trắng, bố trí thành hình vuông.",
      "meaning_or_specification": "Bảng bố trí đèn tín hiệu (không có chức năng điều khiển trực tiếp)."
    },
    {
      "identifier": "Dạng đèn 7",
      "visual_or_geometric_features": "2 đèn tròn: một đèn hình người đứng màu đỏ, một đèn hình người đi màu xanh; bố trí theo chiều dọc hoặc ngang.",
      "meaning_or_specification": "Điều khiển người đi bộ: đèn đỏ – không được đi; đèn xanh – được đi trong phần đường dành cho người đi bộ."
    },
    {
      "identifier": "Dạng đèn 8",
      "visual_or_geometric_features": "2 đèn hiển thị số (kiểu 1: thấp, kiểu 2: cao), chữ số có thể đổi màu xanh/đỏ.",
      "meaning_or_specification": "Đèn đếm lùi thời gian còn lại của tín hiệu đèn (xanh: còn thời gian; đỏ: hết thời gian)."
    },
    {
      "identifier": "Dạng đèn 9",
      "visual_or_geometric_features": "Đèn hình tròn hoặc chữ (ví dụ: 'DỪNG NGAY') nhấp nháy.",
      "meaning_or_specification": "Cảnh báo nguy hiểm; nội dung chữ có thể thay đổi tùy yêu cầu."
    }
  ]
}
